<?php
namespace App\Http\Controllers; use App\Models\{LearningGoal,LearningSession}; use Illuminate\Http\Request;
class LearningController extends Controller {
 public function index(){ $goals=LearningGoal::where('user_id',auth()->id())->latest()->paginate(20); $sessions=LearningSession::where('user_id',auth()->id())->orderByDesc('date')->paginate(20); return view('learning.index',compact('goals','sessions')); }
 public function createGoal(){ return view('learning.create-goal'); } public function createSession(){ $goals=LearningGoal::where('user_id',auth()->id())->get(); return view('learning.create-session',compact('goals')); }
 public function storeGoal(Request $r){ $v=$r->validate(['title'=>'required|string','description'=>'nullable|string','skill'=>'nullable|string','type'=>'nullable|string','target_date'=>'nullable|date','progress_percentage'=>'nullable|integer|between:0,100','status'=>'nullable|string','resource_link'=>'nullable|url']); LearningGoal::create(array_merge($v,['user_id'=>auth()->id()])); return redirect()->route('learning.index'); }
 public function storeSession(Request $r){ $v=$r->validate(['topic'=>'required|string','date'=>'required|date','duration_minutes'=>'required|integer|min:1','learning_goal_id'=>'nullable|exists:learning_goals,id','skill'=>'nullable|string','notes'=>'nullable|string','resource_link'=>'nullable|url']); LearningSession::create(array_merge($v,['user_id'=>auth()->id()])); return redirect()->route('learning.index'); }
 public function editGoal(LearningGoal $goal){ abort_unless($goal->user_id===auth()->id(),403); $item=$goal; return view('learning.edit-goal',compact('item')); }
 public function updateGoal(Request $r,LearningGoal $goal){ abort_unless($goal->user_id===auth()->id(),403); $v=$r->validate(['title'=>'required|string','description'=>'nullable|string','skill'=>'nullable|string','type'=>'nullable|string','target_date'=>'nullable|date','progress_percentage'=>'nullable|integer|between:0,100','status'=>'nullable|string','resource_link'=>'nullable|url']); $goal->update($v); return redirect()->route('learning.index'); }
 public function destroyGoal($goal){ $goal=LearningGoal::withTrashed()->find($goal); if(!$goal) return redirect()->route('learning.index')->with('success','Already deleted'); abort_unless($goal->user_id===auth()->id(),403); if($goal->trashed()) return redirect()->route('learning.index')->with('success','Already deleted'); $goal->delete(); return redirect()->route('learning.index')->with('success','Learning goal deleted'); }
 public function destroySession($session){ $session=LearningSession::find($session); if(!$session) return redirect()->route('learning.index')->with('success','Already deleted'); abort_unless($session->user_id===auth()->id(),403); $session->delete(); return redirect()->route('learning.index')->with('success','Learning session deleted'); }
}